# 課題2の関数(自分で書いたものに置き換えてもかまいません)
def total_score(student):
    return sum(student["scores"].values())

def average_by_class(students):
    sums = {}
    counts = {}
    for s in students:
        c = s["class"]
        sums[c] = sums.get(c, 0) + total_score(s)
        counts[c] = counts.get(c, 0) + 1
    result = {}
    for c in sums:
        result[c] = sums[c] / counts[c]
    return result

print(average_by_class(students))
